<template>
  <component :is="layoutComponent" />
</template>

<script lang="ts">
import { defineComponent, shallowRef, computed } from 'vue';
import { LocalStorage } from 'quasar';
import MainLayout from 'src/layouts/MainLayout.vue';
import PublicLayout from 'src/layouts/PublicLayout.vue';

// Picks MainLayout for authenticated users (full app shell with SideMenu +
// global QuickSearchModal) and PublicLayout for everyone else (bare canvas
// for the minimal logged-out 404). The child Error page reads the same
// auth signal and adjusts its content to match.
export default defineComponent({
  name: 'ErrorRouteLayout',
  setup() {
    const isAuthed = shallowRef(!!(LocalStorage.getItem('token_details') as any)?.access_token);
    const layoutComponent = computed(() => (isAuthed.value ? MainLayout : PublicLayout));
    return { layoutComponent };
  },
});
</script>
